-- Idempotency assertions: dash tables must be byte-identical after a re-run
-- (compared against the _snap_* temp tables captured after the previous run),
-- and every etl_run_log row must show mismatch = 0.
DO $$
DECLARE
    diff_cat  bigint;
    diff_ctry bigint;
    runs      bigint;
    bad_runs  bigint;
BEGIN
    SELECT COUNT(*) INTO diff_cat FROM (
        (SELECT * FROM _snap_cat  EXCEPT SELECT * FROM dash_revenue_by_category)
        UNION ALL
        (SELECT * FROM dash_revenue_by_category EXCEPT SELECT * FROM _snap_cat)
    ) d;
    SELECT COUNT(*) INTO diff_ctry FROM (
        (SELECT * FROM _snap_ctry EXCEPT SELECT * FROM dash_revenue_by_country)
        UNION ALL
        (SELECT * FROM dash_revenue_by_country EXCEPT SELECT * FROM _snap_ctry)
    ) d;
    SELECT COUNT(*) INTO runs     FROM etl_run_log;
    SELECT COUNT(*) INTO bad_runs FROM etl_run_log WHERE mismatch <> 0;

    IF diff_cat <> 0 OR diff_ctry <> 0 THEN
        RAISE EXCEPTION 'IDEMPOTENCY FAIL: category diff=% rows, country diff=% rows', diff_cat, diff_ctry;
    END IF;
    IF bad_runs <> 0 THEN
        RAISE EXCEPTION 'IDEMPOTENCY FAIL: % etl_run_log rows with nonzero mismatch', bad_runs;
    END IF;
    RAISE NOTICE 'IDEMPOTENCY OK: dash tables identical across runs; % log rows so far, all mismatch=0', runs;
END $$;

